import json,pathlib,datetime,copy
p=pathlib.Path(__file__).parent;g=json.loads((p/'dag.json').read_text());before=copy.deepcopy(g)
by={n['id']:n for n in g['nodes']}
by['array']['answer']='An array stores equal-size slots next to each other. If the first slot starts at address b and each slot occupies s units, index i starts at b+i*s. This arithmetic selects the slot directly, without testing earlier entries. The fixed-size word arithmetic and direct memory access are constant-cost primitives in this model; an address identifies a storage location.'
by['array']['status']='supported';by['array']['evidence'].append({'url':'https://opendsa-server.cs.vt.edu/OpenDSA/Books/Catalog/html/Arrays.html','locator':'Opening array definition; §0.10.2 Accessing Items in Arrays','claim':'Contiguous same-type storage and numeric indexing. b+i*s is an arithmetic derivation from equal-size contiguous slots, not a quotation.'})
g['sources'].append({'id':'opendsa-arrays','title':'0.10 Arrays — OpenDSA Complete Catalog','publisher':'OpenDSA Project Contributors','url':'https://opendsa-server.cs.vt.edu/OpenDSA/Books/Catalog/html/Arrays.html','section_locator':'Opening definition and §0.10.2','use':'Contiguous storage; derive address calculation with explicit equal-size-slot model.'})
by['reindex']['answer']+=' Redistribution can split a collision caused by the old remainder, but keys with equal codes still share an index under any capacity-only remainder change.'
by['amortized']['answer']='At a fixed positive load threshold, doubling allocates a new bucket array and redistributes the stored entries. The capacity and entry count are proportional at those growth points, so rebuilding costs O(n) under constant-cost placement. Capacities 1,2,4,... form a sum less than twice the largest term. Across N insertions from empty, total rebuilding work is O(N), hence O(1) amortized growth overhead per insertion. This averages over a sequence, not over random hashes; one growth insertion can still cost O(n). Bad collision searches can still make total insertion expensive.'
by['keycost']['answer']+=' The numerical example uses small integers with fixed-cost operations.'
by['find']['answer']+=' This works only while stored entries remain in the bucket computed for an equal query key; otherwise searching one bucket could falsely report missing.'
by['hash']['answer']+=' The function is a chosen computation, not a scan of the stored table; the example explicitly supplies it as h(k)=k.'
g['nodes'].append({'id':'placement','question':'What condition makes searching only one bucket correct?','answer':'Every stored entry must be in the bucket computed from its key using the current capacity. Equal query and stored keys must compute the same code, and a stored key’s hash/equality behavior must stay consistent while it is stored. Mutating a key so its code changes can leave its entry in the old bucket.','status':'supported','evidence':[{'url':'https://courses.cis.cornell.edu/courses/cs2110/2026sp/lectures/lec20/','locator':'Hash Tables, invariant and missing-key example, lines 43–57','claim':'Stored-bucket invariant makes a lookup in one bucket sufficient.'},{'url':'https://hkn.eecs.berkeley.edu/examfiles/cs61bl_su14_mt2_sol.pdf','locator':'Question 1(a), page 1','claim':'Equal keys need equal codes and repeated calls on unchanged keys give the same code; mutation failure is a derived example.'}]})
g['edges'] += [{'from':'hash','to':'placement','why':'Correct placement for an equal query relies on the equal-key/equal-code contract.'},{'from':'index','to':'placement','why':'The invariant names the bucket produced from the code and current capacity.'},{'from':'placement','to':'find','why':'Searching only that bucket can prove absence only if every matching entry would be there.'}]
by['target']['status']='supported';by['target']['evidence']=[{'url':s['url'],'locator':s['section_locator'],'claim':'Synthesis of the prerequisite nodes; numerical trace separately records original calculations.'} for s in g['sources'][:3]]
g['worked_examples']=[{'id':'tiny-trace','type':'constructed numerical example, not measurement','given_inputs':{'hash':'h(k)=k for small nonnegative integer keys','initial_capacity':4,'new_distinct_key_growth_rule':'If n+1>m, double m before storing the new entry.','bucket_order':'Append new entries; retain relative order during redistribution.','entries':[[1,'A'],[5,'B'],[2,'C'],[3,'D']]},'steps':[{'operation':'Insert the four entries','indices':['1 mod 4 = 1','5 mod 4 = 1','2 mod 4 = 2','3 mod 4 = 3'],'buckets':[[],[[1,'A'],[5,'B']],[[2,'C']],[[3,'D']]],'n':4,'m':4,'load':1},{'operation':'Lookup 5','hash':5,'index':1,'comparisons':['5 == 1: false','5 == 5: true'],'result':'B'},{'operation':'Lookup 9 before insertion','hash':9,'index':1,'comparisons':['9 == 1: false','9 == 5: false'],'result':'missing; the sequence ended'},{'operation':'Insert 9:E; 4+1>4 triggers growth','new_capacity':8,'old_entries_redistributed':4,'old_key_new_indices':{'1':1,'5':5,'2':2,'3':3},'new_key_index':1,'buckets':[[],[[1,'A'],[9,'E']],[[2,'C']],[[3,'D']],[],[[5,'B']],[],[]],'n':5,'m':8,'load':0.625},{'operation':'Lookup 5 after growth','hash':5,'index':5,'comparisons':['5 == 5: true'],'result':'B'}],'interpretation':'The hash codes stayed fixed; the capacity-dependent index changed for key 5. Keys 1 and 9 still collide. The bucket array has empty slots after growth, using extra storage to reduce average bucket length. This example proves neither a uniform hash distribution nor measured performance.'}]
changes=[]
old={n['id']:n for n in before['nodes']}
for n in g['nodes']:
 if old.get(n['id']) != n:changes.append({'id':n['id'],'before':old.get(n['id']),'after':n})
r={'round':7,'timestamp':datetime.datetime.now(datetime.timezone.utc).isoformat(),'gaps':['Array mechanism','Placement invariant exposed by correctness review','Trace must distinguish code collisions from bucket collisions'],'actions':['Read OpenDSA opening definition and accessing-array section.','Derived address formula from contiguous equal-size slots.','Reviewed existing graph for missing-key correctness and insertion-cost scope.','Constructed tiny four-to-eight-bucket trace.'],'edits':changes,'edge_additions':g['edges'][len(before['edges']):],'worked_examples_added':['tiny-trace'],'remaining_gaps':[]};g['revisions'].append(r)
(p/'dag.json').write_text(json.dumps(g,indent=2)+'\n');(p/'dag.round07.json').write_text(json.dumps(g,indent=2)+'\n')
